{
    const MCpti_CallbackData *cbInfo = (MCpti_CallbackData *)cbdata;

    // Take this code path when MCPTI detach is requested
    if (detachMcpti) {
        switch(domain)
        {
        case MCPTI_CB_DOMAIN_RUNTIME_API:
        case MCPTI_CB_DOMAIN_DRIVER_API:
            if (cbInfo->callbackSite == MCPTI_API_EXIT) {
                // call the MCPTI detach API
                mcptiFinalize();
            }
            break;
        default:
            break;
        }
    }
}

